;------------------------------------------------------------------------------
; PrintLevelHead: in a dungeon, "LVL:0" and the level 1-8 at column 9 of row 0 (?), and
; "Head-" with the facing (FacingNames) at 1707h. Uses: nothing (keeps the cursor).
; Callers: DUNMOVE 831E, 83A1.
;------------------------------------------------------------------------------
PrintLevelHead:	pushf	;@62FD
	push ax	;@62FE
	push bx	;@62FF
	push dx	;@6300
	push si	;@6301
	push word ptr CursorCol	;@6302
	mov dx, 9	; DH = row, DL = column (?)	;@6306
	lea si, MsgLvl	;@6309
	call PrintAt	;@630D
	mov al, byte ptr DungeonLevel	;@6310
	add al, 31h	; '1'-'8'	;@6313
	call PutChar	;@6315
	mov dx, 1707h	;@6318
	lea si, MsgHead	;@631B
	call PrintAt	;@631F
	mov bl, byte ptr Facing	; 0-3	;@6322
	mov bh, 0	;@6326
	shl bx, 1	;@6328
	mov si, word ptr FacingNames[bx]	;@632A
	call PrintStr	;@632E
	pop word ptr CursorCol	;@6331
	pop si	;@6335
	pop dx	;@6336
	pop bx	;@6337
	pop ax	;@6338
	popf	;@6339
	ret	;@633A
;------------------------------------------------------------------------------
; MonStepToPlayer: one step of creature SI toward the party: CL, CH = the step in x, y
; (-1, 0, 1: SignStep of the difference), DL, DH = the creature's x, y plus the step
; (wrapped to 0-63). In: SI = creature slot. Callers: WORLD 233D, 23C2, 23E9.
;------------------------------------------------------------------------------
MonStepToPlayer:	pushf	;@633B
	push ax	;@633C
	mov al, byte ptr PlayerXY	; the party's x	;@633D
	mov dl, byte ptr MonX[si]	;@6340
	sub al, dl	;@6344
	call SignStep	;@6346
	mov cl, ah	;@6349
	add dl, cl	;@634B
	and dl, 3Fh	;@634D
	mov al, byte ptr PlayerY	; PlayerY = the party's y	;@6350
	mov dh, byte ptr MonY[si]	;@6353
	sub al, dh	;@6357
	call SignStep	;@6359
	mov ch, ah	;@635C
	add dh, ch	;@635E
	and dh, 3Fh	;@6360
	pop ax	;@6363
	popf	;@6364
	ret	;@6365
;------------------------------------------------------------------------------
; EnterShrine: Enter on a shrine (map byte 0F8h) in Ambrosia. "Who enters?": the player
; offers gold in hundreds ("Offering*100-"); the stat of this shrine (the party's x & 3:
; Strength, Dexterity, Intelligence, Wisdom) rises by the offering, at most the race's
; maximum (RaceStatMax); gold paid beyond that is lost. More than the player has: "You
; can't cheat the Gods!"; 0: "Then be off!". The shrine picture is shown with Location 4,
; and Location is 0FFh (Ambrosia) again at the end. Caller: the Enter command (LOOP 1D85).
;------------------------------------------------------------------------------
EnterShrine:	pushf	;@6366
	push ax	;@6367
	push bx	;@6368
	push cx	;@6369
	push dx	;@636A
	lea si, MsgShrineWho	;@636B
	call PrintMsg	;@636F
	call AskPlayer	;@6372
	jne Shrine_Chosen	;@6375
	jmp Shrine_Done	;@6377
Shrine_Chosen:	dec al	; AL = slot 0-3	;@637A
	mov bp, ax	;@637C
	call IsUp	; ZF: good or poisoned	;@637E
	je Shrine_Enter	;@6381
	jmp Shrine_Incap	;@6383
Shrine_Enter:	push bx	;@6386
	lea bx, StartUp	; load SHRINE.IMG into the view buffer	;@6387
	mov cx, 79h	;@638B
	lea dx, FileShrineImg	;@638E
	call LoadFile	;@6392
	call DrawView	;@6395
	mov byte ptr Location, 4	; 4: a shrine	;@6398
	pop bx	;@639D
	lea si, MsgWelcomeShrine	;@639E
	call PrintMsg	;@63A2
	mov al, byte ptr PlayerXY	;@63A5
	and al, 3	;@63A8
	mov dl, al	;@63AA
	mov dh, 0	;@63AC
	mov si, dx	;@63AE
	shl si, 1	;@63B0
	mov si, word ptr ShrineStatNames[si]	;@63B2
	call PrintMsg	;@63B6
	mov al, byte ptr [bx+16h]	; race letter	;@63B9
	mov cx, 5	;@63BC
	lea di, RaceLetters	;@63BF
	repne scasb	;@63C3
	mov di, 5	; DI = race index	;@63C5
	sub di, cx	;@63C8
	dec di	;@63CA
	shl di, 1	; x 4: its RaceStatMax row	;@63CB
	shl di, 1	;@63CD
	xchg bx, dx	;@63CF
	mov cl, byte ptr RaceStatMax[bx+di]	; CL = the stat's maximum	;@63D1
	xchg bx, dx	;@63D5
	mov di, dx	; DI = the stat (0-3)	;@63D7
	lea si, MsgOffering	;@63D9
	call PrintMsg	;@63DD
	call ReadNumber	; AL = offering (BCD)	;@63E0
	cmp al, 0	;@63E3
	je Shrine_NoOffer	;@63E5
	cmp al, byte ptr [bx+24h]	; gold in hundreds (BCD)	;@63E7
	ja Shrine_Cheat	;@63EA
	mov ah, byte ptr [bx+24h]	;@63EC
	xchg al, ah	;@63EF
	sub al, ah	;@63F1
	das	;@63F3
	mov byte ptr [bx+24h], al	; pay	;@63F4
	mov al, byte ptr [bx+di+12h]	; the stat (record 12h-15h)	;@63F7
	add al, ah	;@63FA
	daa	;@63FC
	jb Shrine_Cap	;@63FD
	cmp al, cl	;@63FF
	jbe Shrine_Store	;@6401
Shrine_Cap:	mov al, cl	;@6403
Shrine_Store:	mov byte ptr [bx+di+12h], al	;@6405
	lea si, MsgShazam	;@6408
	call PrintMsg	;@640C
	mov ax, bp	;@640F
	call FlashPlayer	; FlashPlayer	;@6411
	call FlashView	; FlashView	;@6414
	mov al, 0FDh	; sound 0FDh	;@6417
	mov bl, 0D8h	;@6419
	mov bh, 30h	;@641B
	call Sound	;@641D
	call FlashView	; FlashView	;@6420
	mov ax, bp	;@6423
	call FlashPlayer	; FlashPlayer	;@6425
Shrine_Done:	mov byte ptr Location, 0FFh	; Ambrosia	;@6428
	pop dx	;@642D
	pop cx	;@642E
	pop bx	;@642F
	pop ax	;@6430
	popf	;@6431
	ret	;@6432
Shrine_Cheat:	lea si, MsgCantCheat	;@6433
	call PrintMsg	;@6437
	mov al, 0FFh	;@643A
	call Sound	;@643C
	jmp Shrine_Done	;@643F
Shrine_NoOffer:	lea si, MsgThenBeOff	;@6441
	call PrintMsg	;@6445
	jmp Shrine_Done	;@6448
Shrine_Incap:	lea si, TxtIncapacitated	; "Incapacitated!"	;@644A
	call PrintMsg	;@644E
	mov al, 0FFh	;@6451
	call Sound	;@6453
	jmp Shrine_Done	;@6456
;------------------------------------------------------------------------------
; ExitToSosaria: leave a dungeon: back to the entrance (PartyXY), the map wraps again,
; "Exit to Sosaria!", reload SOSARIA.ULT into the map buffer, draw the moons, level 0.
; LightOn is not cleared here. Uses: nothing (saves all). Callers: the main loop (1C04),
; Sur Acron, Sequitu, Klimb on the first level (DUNMOVE 8416).
;------------------------------------------------------------------------------
ExitToSosaria:	push ax	;@6458
	push bx	;@6459
	push cx	;@645A
	push dx	;@645B
	push si	;@645C
	mov ax, word ptr PartyXY	;@645D
	mov word ptr PlayerXY, ax	;@6460
	mov byte ptr MapWraps, 0FFh	; MapWraps = MapWraps	;@6463
	lea si, MsgExitToSosaria	;@6468
	call PrintMsg	;@646C
	mov byte ptr Location, 0	;@646F
	lea bx, MapBuf	;@6474
	mov cx, 1228h	; 4648 bytes	;@6478
	lea dx, FileSosariaUlt	;@647B
	call LoadFile	;@647F
	call SaveParty	; draw the moons (?)	;@6482
	mov byte ptr DungeonLevel, 0	;@6485
	call FlushKeys	;@648A
	pop si	;@648D
	pop dx	;@648E
	pop cx	;@648F
	pop bx	;@6490
	pop ax	;@6491
	ret	;@6492
; 13 zero bytes, not referenced.
	db 0h,0h,0h,0h,0h,0h,0h,0h,0h,0h,0h,0h,0h	;@6493
